package com.rvmeur.transferin.domain.exposure

/**
 * Exposure classification verdict generated by [ExposureAnalyzer].
 */
enum class ExposureClassification {
    /**
     * Exposure distribution is acceptable, well-balanced, or artistic high/low key.
     */
    OPTIMAL,

    /**
     * Severe flash misfire or total underexposure.
     */
    UNDEREXPOSED_CRITICAL,

    /**
     * Severe strobe burnout or unrecoverable highlight blowout.
     */
    OVEREXPOSED_BLOWN
}

/**
 * Complete result containing exposure verdict, statistical metrics, and execution latency.
 */
data class ExposureAnalysisResult(
    val classification: ExposureClassification,
    val metrics: ExposureMetrics,
    val executionTimeMs: Float = 0.0f
) {
    val meanLuminance: Float get() = metrics.meanLuminance
    val blackFloorDensity: Float get() = metrics.blackFloorDensity
    val shadowClippingPercent: Float get() = metrics.shadowClippingPercent
    val highlightSaturationPercent: Float get() = metrics.highlightSaturationPercent
    val shannonEntropy: Float get() = metrics.shannonEntropy
    val histogramBins: IntArray get() = metrics.histogramBins
    val totalPixels: Int get() = metrics.totalPixels
}
